<div class="page-heading"><div><span class="eyebrow">BETTER TOGETHER</span><h1>Your team</h1><p>Manage access to <?= e(workspace()['name']) ?>.</p></div><button class="button primary" data-dialog="invite-dialog"><?= icon('plus') ?>Invite member</button></div><?php if($error): ?><div class="notice error" role="alert"><?= e($error) ?></div><?php endif ?>
<?php if(isset($_SESSION['invite_link'])): ?><div class="notice"><div><strong>Invitation created</strong><p>Share this private link with your invitee. It expires in 7 days.</p><input class="share-link" aria-label="Invitation link" readonly value="<?= e($_SESSION['invite_link']) ?>"></div></div><?php unset($_SESSION['invite_link']); endif ?>
<div class="table-wrap"><table><thead><tr><th>Member</th><th>Email</th><th>Role</th><th>Actions</th></tr></thead><tbody><?php foreach($members as $member): ?><tr><td><div class="row-title"><span class="avatar"><?= e(mb_strtoupper(mb_substr($member['name'],0,1))) ?></span><strong><?= e($member['name']) ?></strong></div></td><td><?= e($member['email']) ?></td><td><?= badge($member['role']) ?></td><td><?php if($member['role']!=='owner'): ?><form class="inline-form" method="post"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= $member['id'] ?>"><select name="role" aria-label="Role for <?= e($member['name']) ?>"><option value="member"<?= selected($member['role'],'member') ?>>Member</option><option value="manager"<?= selected($member['role'],'manager') ?>>Manager</option></select><button class="icon-button" name="action" value="role" title="Save role" aria-label="Save role"><?= icon('check') ?></button><button class="icon-button negative" name="action" value="remove" data-confirm="Remove this person's workspace access?" title="Remove member" aria-label="Remove member"><?= icon('x') ?></button></form><?php else: ?><span class="muted">Workspace owner</span><?php endif ?></td></tr><?php endforeach ?></tbody></table></div>
<section class="spaced-section"><div class="section-heading"><h2>Pending invitations</h2></div><?php if(!$invitations): ?><p class="muted">No pending invitations.</p><?php endif ?><?php foreach($invitations as $invite): ?><div class="simple-row"><div><strong><?= e($invite['email']) ?></strong><small><?= ucfirst($invite['role']) ?> &middot; Expires <?= short_date($invite['expires_at']) ?></small></div><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $invite['id'] ?>"><button class="button small" name="action" value="revoke">Revoke</button></form></div><?php endforeach ?></section>
<div class="role-explainer"><p><strong>Owner</strong> Company settings, team and all finances.</p><p><strong>Manager</strong> Company finances, approvals and reports.</p><p><strong>Member</strong> Only their own expenses and uploaded documents.</p></div>
<dialog id="invite-dialog"><div class="dialog-heading"><h2>Invite a teammate</h2><button class="icon-button" data-close-dialog aria-label="Close" title="Close"><?= icon('x') ?></button></div><form method="post" class="stack-form"><?= csrf_field() ?><input type="hidden" name="action" value="invite"><label>Email<input type="email" name="email" maxlength="190" required></label><label>Role<select name="role"><option value="member">Member</option><option value="manager">Manager</option></select></label><button class="button primary"><?= icon('mail') ?>Create invitation</button></form></dialog>
